async function refresh(){if(pending)return false;return readState();}
function checkInvite(){const token=new URL(location.href).searchParams.get('invite');if(!token)return;dialog('Приглашение в группу',`${user.guest?`<p class="muted">Создайте аккаунт или войдите, чтобы принять приглашение.</p>${btn('Создать аккаунт','account','','primary')}${btn('Войти','login','','secondary')}`:btn('Присоединиться','join',token,'primary','team')}`);}
async function bootstrap(){
 const epoch=++contextEpoch;drafts.migrate();const cached=drafts.offline();
 try{if(!await readState())return;authNotice='';render();if(data)checkInvite();if(pending)toast(conflict?'Восстановлен черновик с конфликтом. Экспортируйте его и сравните с серверной версией в настройках.':'Восстановлен ваш черновик. Проверьте изменения и нажмите «Синхронизировать» в настройках.');}
 catch(e){if(epoch!==contextEpoch)return;if(e.status===401){sessionExpired(cached?.pending?saveFailure(e,localSaved):'');}else if(!e.status&&cached?.user&&!cached.user.guest){data=cached.state;user=cached.user;members=cached.members;revision=cached.revision;pending=cached.pending;conflict=cached.conflict;render();toast('Открыта локальная копия библиотеки');}else{app.innerHTML='<div class="boot"><img src="/icon.svg" width="64" alt="Psalmony"><h1>Нет связи с сервером</h1><p>Проверьте интернет и попробуйте снова. Локальные черновики сохранены отдельно для вашего аккаунта.</p><button class="btn primary" id="retry">Повторить</button></div>';$('#retry').onclick=bootstrap;}}
}
window.addEventListener('online',()=>{updateSync();});window.addEventListener('offline',updateSync);
window.addEventListener('beforeunload',e=>{if(pending){cache();e.preventDefault();e.returnValue='';}});
setInterval(async()=>{if(!data||stage||modal.open||contextBusy||document.hidden||syncBusy||document.activeElement?.matches('input,textarea,select'))return;if(pending)return;const epoch=contextEpoch;try{const old=revision,fresh=await api('/state');if(epoch!==contextEpoch)return;if(JSON.stringify(fresh.user)!==JSON.stringify(user)||fresh.revision!==old||JSON.stringify(fresh.members)!==JSON.stringify(members)){apply(fresh);render();}}catch(e){if(epoch===contextEpoch&&e.status===401)sessionExpired();}},8000);
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
function openArrangement(id){
 const song=data.songs.find(s=>s.id===id);
 arrangementDraft={songId:id,title:song.title,value:structuredClone(song.arrangement||arrangementFromLyrics(song.lyrics))};
 dialog('Аранжировка · '+esc(song.title),'<div id="arrangement-editor"></div>',true);renderArrangement();
}
function renderArrangement(){
 const a=arrangementDraft.value;
 $('#arrangement-editor').innerHTML=`<p class="muted small">Отредактируйте блок один раз — изменения появятся во всех его повторениях. Исходная песня изменится только после сохранения.</p><div class="arrangement-layout"><section><h3>Блоки песни</h3>${a.blocks.map((b,i)=>`<article class="arr-block"><div><input aria-label="Название блока ${i+1}" maxlength="100" value="${esc(b.title)}" data-arr-block="${b.id}" data-arr-field="title">${ib('Удалить блок '+(i+1),'arr-remove-block',b.id,'trash')}</div><textarea aria-label="Текст блока ${i+1}" rows="4" data-arr-block="${b.id}" data-arr-field="lyrics">${esc(b.lyrics)}</textarea>${btn('Добавить в форму','arr-append',b.id,'text','plus')}</article>`).join('')}${a.blocks.length<64?btn('Новый блок','arr-add-block','','secondary','plus'):''}</section><section class="arr-order"><h3>Порядок исполнения</h3><p class="muted small">Перетаскивайте блоки или используйте стрелки.</p>${a.order.map((id,i)=>`<div class="arr-order-item" draggable="true" data-order-index="${i}"><span>${i+1}</span><b>${esc(a.blocks.find(b=>b.id===id)?.title)}</b>${ib('Выше в форме '+(i+1),'arr-move',i+'|-1','up')}${ib('Ниже в форме '+(i+1),'arr-move',i+'|1','down')}${ib('Убрать повтор '+(i+1),'arr-remove',String(i),'close')}</div>`).join('')||'<p class="muted">Добавьте блоки кнопками слева.</p>'}<p class="muted small">${a.order.length} разделов · ${arrangementText(a).length} символов</p></section></div><div class="modal-actions">${btn('Отмена','close','','secondary')}${btn('Сохранить аранжировку','save-arrangement','','primary','check')}</div>`;
 let dragged=null;
 $$('.arr-order-item').forEach(row=>{row.ondragstart=e=>{dragged=Number(row.dataset.orderIndex);e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(dragged));};row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();if(dragged===null)return;const [id]=a.order.splice(dragged,1);a.order.splice(Number(row.dataset.orderIndex),0,id);dragged=null;renderArrangement();};});
}

async function updateOfflineStatus(id){
 const target=$('#offline-set-status');if(!target||target.dataset.set!==id)return;
 try{const set=data.setlists.find(s=>s.id===id),bundle=collectBundle(set,data.songs),saved=await readOfflineSet(user.bandId,id);const result=await inspectBundle(bundle,saved,file=>readFile(user.bandId,file));const shell=await shellReady();if(!target.isConnected)return;
 target.textContent=!shell?'Оболочка ещё не сохранена. Обновите страницу при подключённом сервере.':({missing:'Ещё не скачано на это устройство',stale:'Программа изменилась — обновите скачанную версию',incomplete:`Не хватает файлов: ${result.missing}`,ready:`Готово офлайн · Песни: ${bundle.songs.length} · Файлы: ${bundle.files.length}`})[result.status];
 target.classList.toggle('ready',shell&&result.status==='ready');
 const open=$('#offline-set-open');if(open)open.innerHTML=saved?btn('Открыть скачанную версию','open-offline-set',id,'back-link','play'):'';
 }catch(e){if(target.isConnected)target.textContent='Не удалось проверить хранилище: '+e.message;}
}
async function downloadSet(id){
 const band=user.bandId;const set=data.setlists.find(s=>s.id===id);const bundle=collectBundle(set,data.songs);
 const totalBytes=bundle.files.reduce((sum,f)=>sum+f.size,0),links=bundle.songs.reduce((n,s)=>n+s.links.length,0);
 dialog('Скачать выступление',`<div class="download-summary"><span class="tool-icon blue">${icon('download')}</span><h3>${esc(set.title)}</h3><p>Песни: ${bundle.songs.length} · Файлы: ${bundle.files.length} · ${(totalBytes/1024/1024).toFixed(1)} МБ</p></div><progress id="download-progress" max="${Math.max(1,bundle.files.length)}" value="0"></progress><p id="download-status" role="status">Проверяем оболочку приложения…</p><p class="muted small">Сохраняются тексты, аранжировки, ноты, аудио, паузы и заметки.${links?' Внешние ссылки ('+links+') требуют интернета.':''} Браузер может освобождать хранилище — проверяйте готовность перед выходом.</p><div id="download-actions">${btn('Остановить','download-cancel','','secondary')}</div>`);
 const controller=new AbortController();offlineController=controller;
 try{
   if(!await shellReady())throw new Error('Оболочка ещё не сохранена. Обновите страницу при доступном сервере и повторите скачивание.');
   const space=await navigator.storage?.estimate();if(space?.quota&&space.quota-space.usage<totalBytes)toast('Свободного места может не хватить. Уже скачанные файлы будут использованы повторно.');
   await prepareBundle(bundle,{read:fid=>readFile(band,fid),write:(fid,blob)=>cacheFile(band,fid,blob),download:async(file,signal)=>{const r=await fetch('/api/files/'+encodeURIComponent(file.id),{signal});if(!r.ok)throw new Error(`Не удалось скачать «${file.name}» (${r.status}). Проверьте подключение и доступ.`);return r.blob();},save:manifest=>saveOfflineSet(band,id,manifest)},{signal:controller.signal,onProgress:progress=>{if(offlineController!==controller)return;$('#download-progress').value=progress.done;$('#download-status').textContent=`${progress.done} / ${progress.total} · ${progress.name}`;}});
   if(offlineController===controller&&$('#download-status')){$('#download-status').textContent='Готово. Выступление сохранено на этом устройстве.';$('#download-progress').value=Math.max(1,bundle.files.length);$('#download-actions').innerHTML=btn('Открыть скачанную версию','open-offline-set',id,'primary','play')+btn('Закрыть','close','','secondary');}
 }catch(e){if(offlineController===controller&&$('#download-status')){$('#download-status').textContent=e.name==='AbortError'?'Скачивание остановлено. Готовые файлы сохранены; можно продолжить позже.':e.name==='QuotaExceededError'?'На устройстве не хватило места. Освободите память и повторите скачивание.':e.message;$('#download-actions').innerHTML=btn('Повторить','download-set',id,'primary')+btn('Закрыть','close','','secondary');}}
 finally{if(offlineController===controller)offlineController=null;updateOfflineStatus(id);}
}

function partBar(song){return `<nav class="stage-parts" aria-label="Форма песни">${songParts(song).map((part,i)=>`<button data-action="stage-part" data-id="${i}" class="${stage.part===i?'active':''}" aria-current="${stage.part===i?'step':'false'}">${i+1}. ${esc(part.title)}</button>`).join('')}</nav>`;}
function focusStagePart(){const scroll=$('#stage-scroll'),part=$(`[data-part-index="${stage.part}"]`);if(scroll&&part)scroll.scrollTop=part.offsetTop-scroll.offsetTop;}
function liveBar(){const l=stage.live;if(!l)return stage.offline?'<div class="live-bar"><span>Скачанная версия · можно играть без интернета</span></div>':'';return `<div class="live-bar"><span id="live-status" role="status">${liveStatus()}</span>${l.mode==='follow'?btn(l.paused?'Следовать за ведущим':'Самостоятельно','toggle-follow','','glass'):''}</div>`;}
function liveStatus(){const l=stage?.live;if(!l)return '';if(l.lost)return 'Нет связи с группой · последняя песня доступна';return l.mode==='lead'?'Вы ведёте группу · песня и раздел передаются участникам':l.paused?'Самостоятельный просмотр · эфир подключён':'Ведущий: '+esc(l.name);}
function updateLiveStatus(){const el=$('#live-status');if(el)el.innerHTML=liveStatus();}
async function liveRoom(){
 dialog('Эфир группы','<p class="muted">Ищем ведущего…</p>');
 const live=await api('/live');
 if(!modal.open)return;
 dialog('Эфир группы',live.active?`<span class="tag">В ЭФИРЕ</span><h3 class="live-room-title">${esc(live.setTitle)}</h3><p>Ведущий: <b>${esc(live.leaderName)}</b>. Песня и раздел будут переключаться вместе с ним; тональность, капо и размер текста останутся вашими.</p>${btn('Следовать за ведущим','follow-live','','primary','team')}${user.role==='owner'?btn('Завершить эфир','stop-band-live',live.id,'secondary'):''}`:'<p>Сейчас никто не ведёт группу.</p><p class="muted">Откройте комнату из сет-листа и нажмите «Вести программу». Участники смогут подключиться здесь. Для совместного режима нужен доступ к одному серверу.</p>');
}
async function beginLive(setId){
 await saveQueue;if(pending)await sync();if(pending)throw new Error('Сначала синхронизируйте библиотеку и разрешите конфликты');
 const live=await api('/live/start',{method:'POST',body:JSON.stringify({setId,libraryRevision:revision})});
 closeModal();startStage(live.snapshot.items,{songs:live.snapshot.songs,live:{id:live.id,token:live.controlToken,revision:live.revision,mode:'lead',name:live.leaderName,lost:false,busy:false}});
 liveTimer=setInterval(publishLive,5000);
}
async function followLive(){
 const live=await api('/live?full=1');if(!live.active)throw new Error('Эфир уже закончился');
 closeModal();startStage(live.snapshot.items,{songs:live.snapshot.songs,index:live.position.index,part:live.position.part,live:{id:live.id,revision:live.revision,mode:'follow',name:live.leaderName,paused:false,busy:false,lost:false}});
 restoreView(stage.items[stage.index]?.songId,true);renderStage();liveTimer=setInterval(pollLive,700);
}
async function publishLive(){
 const live=stage?.live;if(!live||live.mode!=='lead'||live.busy)return;
 const position={index:stage.index,part:stage.part};live.busy=true;
 try{const result=await api('/live',{method:'PATCH',body:JSON.stringify({id:live.id,controlToken:live.token,revision:live.revision,position})});if(stage?.live!==live)return;live.revision=result.revision;live.lost=false;}
 catch(e){if(stage?.live!==live)return;live.lost=true;if([401,403,409].includes(e.status)){clearInterval(liveTimer);stage.live=null;renderStage();toast(e.message+' Продолжайте самостоятельно.');}}
 finally{live.busy=false;if(stage?.live===live){updateLiveStatus();if(!live.lost&&(stage.index!==position.index||stage.part!==position.part))publishLive();}}
}
async function pollLive(){
 const live=stage?.live;if(!live||live.mode!=='follow'||live.busy)return;live.busy=true;
 try{const latest=await api('/live');if(stage?.live!==live)return;
  if(!latest.active||latest.id!==live.id){clearInterval(liveTimer);stage.live=null;renderStage();toast('Ведущий завершил эфир или отключился. Можно продолжать самостоятельно.');return;}
  live.lost=false;live.revision=latest.revision;
  if(!live.paused&&(stage.index!==latest.position.index||stage.part!==latest.position.part)){const changedSong=stage.index!==latest.position.index;clearInterval(scrollTimer);scrollTimer=null;clearInterval(breakTimer);breakTimer=null;stopMetro();stage.index=latest.position.index;stage.part=latest.position.part;if(changedSong)restoreView(stage.items[stage.index]?.songId,true);renderStage();}else updateLiveStatus();
 }catch(e){if(stage?.live!==live)return;live.lost=true;updateLiveStatus();if([401,403].includes(e.status)){clearInterval(liveTimer);stage.live=null;renderStage();toast('Доступ к эфиру закрыт.');}}
 finally{live.busy=false;}
}


