document.addEventListener('change',async e=>{const input=e.target;if(!input.dataset.imageKind||!input.files?.[0])return;if(contextBusy){toast('Дождитесь завершения действия с группой');return;}fileWork++;input.disabled=true;try{await saveQueue;if(pending)await sync();if(pending)throw Error('Сначала синхронизируйте изменения');const file=input.files[0];if(file.size>8*1024*1024)throw Error('Изображение должно быть меньше 8 МБ');const r=await fetch('/api/images?kind='+input.dataset.imageKind+'&id='+encodeURIComponent(input.dataset.imageId||''),{method:'POST',headers:{...contextHeaders(),'Content-Type':'application/octet-stream','X-Revision':String(revision)},body:file});const result=await r.json();if(!r.ok){if(r.status===401)sessionExpired(result.error);throw Object.assign(Error(result.error),{status:r.status});}await refresh();closeModal();render();toast('Изображение загружено');}catch(e){toast(e.message);}finally{input.disabled=false;fileWork--;}});

